/**
 * 预编译：按中文 Key 的字符长度严格降序排列的词条数组
 * 保证长句子/长段落优先完整替换，极小词最后匹配，彻底避免语句碎片化！
 */
const SORTED_RULES = Object.entries(PHRASE_DICTIONARY).sort((a, b) => b[0].length - a[0].length);

/**
 * 核心翻译引擎：精确匹配 -> 长词降序扫描替换 -> 繁简体单字字表兜底
 */
export function translateText(raw: string, target: ResolvedLocale): string {
  if (target === 'zh-CN' || !raw) return raw;
  const trimmed = raw.trim();
  if (!trimmed) return raw;

  // 1. 精确完整匹配（最快通道）
  if (PHRASE_DICTIONARY[trimmed]) {
    return raw.replace(trimmed, PHRASE_DICTIONARY[trimmed][target]);
  }

  // 2. 长短语优先扫描替换（先长后短）
  let output = raw;
  for (const [k, v] of SORTED_RULES) {
    if (k.length >= 2 && output.includes(k)) {
      output = output.split(k).join(v[target]);
    }
  }

  // 3. 繁體中文字表兜底：转换任何未被词典显式收录的中文单字
  if (target === 'zh-TW') {
    let twOut = '';
    for (const ch of output) {
      twOut += CHAR_MAP_ZH_TW[ch] || ch;
    }
    return twOut;
  }

  return output;
}
